import typing
from typing import List, TypedDict, Unpack

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class DeleteRecentContentKwargs(TypedDict):
    sticker: list[str]
    emoji: list[str]


class InputMediaMethods(BaseClient):
    """
    Методы группы 'Инпут медиа' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("input.rapi_getRecentContent")
    def rapi_getRecentContent(self, _type: List[str], version: typing.Optional[str] = None) -> dict:
        """
        Получить список media, которые отправлял пользователь

        :param _type: список типов медиа
        :param version: Версия контента пользователя.
        Клиент сохраняет у себя последнюю полученную в ответ на этот метот.
        И отправляет ее при запросе.
        Если версия не была получена в предыдущи раз,
        то клиент не шлёт это поле.
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/getRecentContent",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"type": _type, "version": version} if version else {"type": _type},
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("input.rapi_deleteRecentContent")
    def rapi_deleteRecentContent(self, **kwargs: Unpack[DeleteRecentContentKwargs]) -> dict:
        r"""
        Удалить один или несколько элементов недавнего контента

        param sticker: список хэшей стикеров \n
        param emoji: эмодзи \n
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/deleteRecentContent",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": kwargs,
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("input.rapi_deleteRecentContentByType")
    def rapi_deleteRecentContentByType(self, _type: List[str]) -> dict:
        """
        Удалить весь недавний контент

        :param _type: список типов контента
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/deleteRecentContentByType",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"type": _type},
            },
        )
